148		now, setNow := fixedClock(at(0))
149		b := NewBook(WithClock(now))
150		must := func(r RegisterRequest) {
151			t.Helper()
152			if err := b.RegisterVersion(r); err != nil {
153				t.Fatalf("register %+v: %v", r, err)
154			}
155		}
156		must(RegisterRequest{ItemID: "seat", VersionID: "old", UnitPrice: 100, Start: at(0), End: atPtr(100)})
157		must(RegisterRequest{ItemID: "seat", VersionID: "new", UnitPrice: 200, Start: at(40), Replaces: "old"})
158	
159		views, err := b.ItemVersions("seat")
160		if err != nil {
161			t.Fatal(err)
162		}
163		if len(views) != 2 {
164			t.Fatalf("want 2 versions, got %d", len(views))
165		}
166		old, nv := views[0], views[1]
167		if old.VersionID != "old" || nv.VersionID != "new" {
168			t.Fatalf("unexpected order: %v, %v", old.VersionID, nv.VersionID)
169		}
170		// 登记信息保留，替代关系可见
171		if old.End == nil || !old.End.Equal(at(100)) {
172			t.Fatalf("registered end lost: %v", old.End)
173		}
174		if nv.Replaces != "old" || old.SupersededBy != "new" {
175			t.Fatalf("replacement relation missing: %+v %+v", old, nv)
176		}
177		// 实际有效区间：old 被截断到 new 的开始
178		if old.EffectiveEnd == nil || !old.EffectiveEnd.Equal(at(40)) {
179			t.Fatalf("old effective end: %v", old.EffectiveEnd)
180		}
181		if nv.EffectiveEnd != nil {
182			t.Fatalf("new should be open-ended: %v", nv.EffectiveEnd)
183		}
184	
185		// 新版本到期后，被替代的旧版本不会重新生效：
186		// 用另一个项验证——new 到期后 old 的有效区间仍止于交接点。
187		must(RegisterRequest{ItemID: "hall", VersionID: "old", UnitPrice: 1, Start: at(0), End: atPtr(100)})
188		must(RegisterRequest{ItemID: "hall", VersionID: "new", UnitPrice: 1, Start: at(40), End: atPtr(50), Replaces: "old"})
189		setNow(at(60)) // new 已到期
190		out, err := b.Quote(QuoteRequest{RequestID: "q-hall-old", ItemID: "hall", VersionID: "old", Quantity: 1})
191		if err != nil {
192			t.Fatal(err)
193		}
194		if out.Confirmed || out.Reason != ReasonVersionExpired {
195			t.Fatalf("superseded old version must not revive: %+v", out)
196		}
197		out, err = b.Quote(QuoteRequest{RequestID: "q-hall-new", ItemID: "hall", VersionID: "new", Quantity: 1})
198		if err != nil {
199			t.Fatal(err)
200		}
201		if out.Confirmed || out.Reason != ReasonVersionExpired {
202			t.Fatalf("expired new version: %+v", out)
203		}
204	}
